#!/usr/bin/env python3
"""
The bipartite race: counting versus construction
=================================================

On the height-two ("bipartite") subclass, the two ends of the universal-poset
problem can be computed exactly and raced against each other.

  * LOWER (counting).  There are 2^(kl) bipartite posets with parts of sizes
    k and l, and an induced embedding into an N-point host determines the poset,
    so 2^(kl) <= N^(k+l), i.e. N >= 2^(kl/(k+l)).  Balanced (k = l = m, n = 2m)
    this is N >= 2^(n/4).

  * UPPER (construction).  The tagged-neighbourhood host, with k bottom points
    and all pairs (down-set, tag), has k + 2^k * l points and accommodates every
    single one of them.  Balanced this is m*2^m + m, i.e. 2^(n/2 + o(n)).

This script verifies the construction exhaustively for small (k,l), computes
both bounds, and prints the gap in the exponent -- the factor of two that the
whole subject turns on.  It also demonstrates, by direct search, that the
counting bound is already lossy at the very first nontrivial case: for k = l = 1
counting predicts N >= 2 while the truth is N = 3.

Self-contained: standard library only.
"""

from __future__ import annotations

from itertools import product
from math import log2
from typing import List, Sequence, Tuple

Poset = Tuple[int, ...]


def leq(P: Poset, x: int, y: int) -> bool:
    return (P[x] >> y) & 1 == 1


def bipartite_poset(k: int, l: int, R: Sequence[Sequence[int]]) -> Poset:
    up = [1 << i for i in range(k + l)]
    for a in range(k):
        for b in range(l):
            if R[a][b]:
                up[a] |= 1 << (k + b)
    return tuple(up)


def tagged_host(k: int, l: int) -> Poset:
    """k bottom points, then (S, j) for every subset S and tag j."""
    N = k + (1 << k) * l
    up = [1 << i for i in range(N)]
    for a in range(k):
        for S in range(1 << k):
            if (S >> a) & 1:
                for j in range(l):
                    up[a] |= 1 << (k + S * l + j)
    return tuple(up)


def embed(k: int, l: int, R: Sequence[Sequence[int]]) -> List[int]:
    """The explicit embedding: bottom a -> a; top b -> (N_R(b), b)."""
    f = list(range(k))
    for b in range(l):
        S = sum(1 << a for a in range(k) if R[a][b])
        f.append(k + S * l + b)
    return f


def check(k: int, l: int) -> bool:
    H = tagged_host(k, l)
    for flat in product((0, 1), repeat=k * l):
        R = [[flat[a * l + b] for b in range(l)] for a in range(k)]
        P = bipartite_poset(k, l, R)
        f = embed(k, l, R)
        for x in range(k + l):
            for y in range(k + l):
                if leq(H, f[x], f[y]) != leq(P, x, y):
                    return False
    return True


def is_partial_order(P: Poset) -> bool:
    n = len(P)
    for x in range(n):
        if not leq(P, x, x):
            return False
        for y in range(n):
            if leq(P, x, y):
                if x != y and leq(P, y, x):
                    return False
                for z in range(n):
                    if leq(P, y, z) and not leq(P, x, z):
                        return False
    return True


def all_posets(n: int) -> List[Poset]:
    off = [(i, j) for i in range(n) for j in range(n) if i != j]
    out = []
    for bits in range(1 << len(off)):
        up = [1 << i for i in range(n)]
        for b, (i, j) in enumerate(off):
            if (bits >> b) & 1:
                up[i] |= 1 << j
        P = tuple(up)
        if is_partial_order(P):
            out.append(P)
    return out


def embeds(P: Poset, H: Poset) -> bool:
    n, N = len(P), len(H)
    assign: List[int] = []

    def rec(x: int) -> bool:
        if x == n:
            return True
        for h in range(N):
            if h in assign:
                continue
            if all(leq(H, h, hy) == leq(P, x, y) and leq(H, hy, h) == leq(P, y, x)
                   for y, hy in enumerate(assign)):
                assign.append(h)
                if rec(x + 1):
                    return True
                assign.pop()
        return False

    return rec(0)


def main() -> None:
    print("Exhaustive verification of the tagged-neighbourhood host")
    print("-" * 62)
    print(f"{'k':>3}{'l':>3}{'#posets':>10}{'host size':>11}"
          f"{'counting >=':>13}{'all embed':>11}")
    for k in range(1, 5):
        for l in range(1, 4):
            if k * l > 12:
                continue
            lower = 2.0 ** (k * l / (k + l))
            print(f"{k:>3}{l:>3}{2**(k*l):>10}{k + (1 << k) * l:>11}"
                  f"{lower:>13.3f}{str(check(k, l)):>11}")

    print()
    print("Balanced class n = 2m: exponents")
    print("-" * 62)
    print(f"{'m':>4}{'n':>5}{'log2 counting':>15}{'log2 host':>12}{'ratio':>8}")
    for m in (1, 2, 4, 8, 16, 32, 64):
        lo, hi = m / 2, log2(m * 2 ** m + m)
        print(f"{m:>4}{2*m:>5}{lo:>15.2f}{hi:>12.2f}{hi/lo:>8.2f}")
    print("The ratio tends to 2: the counting bound gives n/4, the explicit")
    print("host gives n/2, and no argument currently decides between them.")

    print()
    print("The counting bound is lossy already at k = l = 1")
    print("-" * 62)
    fam2 = all_posets(2)
    for N in (2, 3):
        hosts = [H for H in all_posets(N) if all(embeds(P, H) for P in fam2)]
        print(f"  hosts on {N} points serving all {len(fam2)} two-point posets: "
              f"{len(hosts)}")
    print("  counting predicts only N >= 2^(1/2), i.e. N >= 2; the truth is 3.")
    print("  Reason: counting lets a host point be reused freely, but a host")
    print("  point that is comparable to another cannot become incomparable.")


if __name__ == "__main__":
    main()

