"""
Algorithm C -- Overlap Certificates and the Geometric Ladder
=============================================================

A purely structural way to force a universal host to be large, using no
counting at all.

Say two n-element posets P, Q have *common induced bound* s if no configuration
of more than s points sits order-isomorphically inside both.  Inside any host,
the images of an induced copy of P and an induced copy of Q intersect in a set
that is simultaneously an induced subposet of P and of Q, hence has at most s
points.  Inclusion-exclusion then forces

        |host|  >=  2n - s.

With k posets and Bonferroni's inequality this becomes

        |host|  >=  k*n  -  sum_{j < i} s_ij .

Two instantiations:

  * chain vs. antichain has s = 1 (two points cannot be comparable and
    incomparable at once), giving U(n) >= 2n - 1;
  * the geometric ladder P_i = disjoint union of r^(k-i) chains of length r^i
    inside n = r^k points has s_ij <= r^(k-i) * r^j for j < i, because a common
    configuration splits into at most one chain per coarse block and each such
    chain lies inside a single fine block.  For r = 4 the geometric series of
    overlaps costs only a third of the demand, leaving
    2k*4^k <= 3*U(4^k), hence n*log_4(n) <= 6*U(n) and U(n)/n -> infinity.
    For r = 2 the bound flatlines at 2n - 2: ratio 2 is the exact threshold.

Complexity: O(k^2) once the certificates s_ij are known; the certificates
themselves are O(1) closed-form for the families above, and O(n! ) by brute
force in general (feasible only for tiny n, used here as a sanity check).
"""

from __future__ import annotations

from typing import Callable, List, Sequence, Tuple

Poset = Tuple[int, ...]


def block_chains(n: int, d: int) -> Poset:
    """Disjoint union of chains of length d: x <= y iff x <= y and x//d == y//d."""
    up = [1 << i for i in range(n)]
    for x in range(n):
        for y in range(x, n):
            if x // d == y // d:
                up[x] |= 1 << y
    return tuple(up)


def block_chain_overlap(n: int, coarse_d: int, fine_d: int) -> int:
    """Certified bound r^(k-i)*r^j in general form: (#coarse blocks) * fine_d."""
    n_coarse_blocks = (n - 1) // coarse_d + 1 if n else 0
    return n_coarse_blocks * fine_d


def overlap_bound(n: int, k: int,
                  s: Callable[[int, int], int]) -> int:
    """Bonferroni lower bound k*n - sum_{j<i} s(i,j) for a family of k posets."""
    total = sum(min(s(i, j), n) for i in range(k) for j in range(i))
    return max(0, k * n - total)


def geometric_ladder_bound(r: int, k: int) -> int:
    """The bound produced by the ruler family of ratio r inside n = r^k points."""
    n = r ** k
    return overlap_bound(n, k, lambda i, j: r ** (k - i) * r ** j)


def chain_antichain_bound(n: int) -> int:
    """U(n) >= 2n - 1."""
    return max(0, 2 * n - 1)


def three_poset_bound(n: int) -> int:
    """U(n) >= 3n - (3 + ceil(n/2)), from chain, antichain and two chains."""
    return max(0, 3 * n - (3 + (n + 1) // 2))


def certificate_table(r: int, kmax: int) -> List[Tuple[int, int, int, float]]:
    """(k, n, bound, bound/n) for the ruler family of ratio r."""
    out = []
    for k in range(1, kmax + 1):
        n = r ** k
        b = geometric_ladder_bound(r, k)
        out.append((k, n, b, b / n))
    return out


def brute_common_induced_bound(P: Poset, Q: Poset) -> int:
    """Exact largest common induced configuration; exponential, small n only."""
    from itertools import combinations, permutations
    n = len(P)

    def leq(R: Poset, x: int, y: int) -> bool:
        return (R[x] >> y) & 1 == 1

    for size in range(n, 0, -1):
        for A in combinations(range(n), size):
            for img in permutations(range(n), size):
                if all(leq(P, A[i], A[j]) == leq(Q, img[i], img[j])
                       for i in range(size) for j in range(size)):
                    return size
    return 0
